{"drafts": [{"draft_id": "80001a4b-8c7e-53b5-88e6-7df86e788096", "doc_id": "1291f40b-7db3-5798-9061-f3310b3f99fe", "name": "未交付货物延迟计分规则", "description": "在场景结束时，对仍未交付的货物按统一公式计算延迟量，用于结算服务评分。适用于场景收尾结算阶段，需要为每个未交付货物给出延迟数值时使用。", "asset_type": "knowledge_reference", "granularity": "session", "asset_node_id": "knowledge_reference_node", "asset_path": "family_root/knowledge_reference_node", "asset_level": 1, "visible_role": "leaf", "objective": "按统一公式计算场景结束时未交付货物的延迟量", "domain": "交通仿真规则", "task_family": "场景结算", "method_family": "延迟计分公式", "stage": "场景收尾结算", "applicable_signals": ["场景已到达最终 tick", "存在仍未交付的货物", "需要为服务评分提供延迟数据"], "contraindications": ["货物已在场景内交付", "场景尚未结束"], "intervention_moves": ["识别场景结束时仍未交付的货物", "对每个未交付货物应用公式 lateness = (FinalTick + 1 − DueTime)", "输出每个未交付货物的延迟数值"], "workflow_steps": ["确认场景已到达最终 tick", "筛选出仍未交付的货物", "对每个未交付货物计算 (FinalTick + 1 − DueTime)", "汇总并输出每个未交付货物的延迟数值"], "triggers": ["场景到达最终 tick 需要结算未交付货物", "需要计算货物延迟以汇总服务评分"], "constraints": ["仅对场景结束时仍未交付的货物计算延迟", "延迟公式固定为 (FinalTick + 1 − DueTime)"], "cautions": ["不要在场景结束前提前结算", "不要对已交付货物重复计算延迟"], "output_contract": ["每个未交付货物的延迟数值列表，可用于汇总服务评分"], "examples": [{"input": "场景到达最终 tick，某货物 DueTime 早于 FinalTick + 1 且仍未交付", "output": "该货物延迟 = FinalTick + 1 − DueTime，为正数", "notes": "延迟量用于服务评分结算"}], "risk_class": "low", "confidence": 0.8, "support_ids": ["94617d5e-7661-5b69-8639-9475692426a5"], "metadata": {"prompt": "当场景到达最终 tick 并需要结算未交付货物时，逐一识别仍未交付的货物，按公式 lateness = (FinalTick + 1 − DueTime) 计算每个货物的延迟量，并输出每个未交付货物的延迟数值。不要对已交付货物计算延迟，也不要在场景结束前使用本规则。", "tags": ["交通仿真", "场景结算", "延迟计分", "未交付货物"], "files": {}, "resources": {}, "source_sections": ["User Questions"], "extraction_unit": "window", "domain_type": "traffic simulation rules", "taxonomy_id": "traffic simulation rules", "asset_node_id": "knowledge_reference_node", "asset_path": "family_root/knowledge_reference_node", "asset_level": 1, "visible_role": "leaf", "candidate_slot": 1, "window_id": "084458f6-b790-5344-852b-7ff8a946c5ff", "window_strategy": "strict", "anchor_hits": [], "paragraph_start": 23, "paragraph_end": 25, "heading_path": ["User Questions"], "parent_heading": "", "sibling_headings": ["CL-Bench: Empirical Discovery & Simulation / Simulation Environment", "System Context"], "subsection_headings": ["1. Overview", "2. Nodes and Edges", "3. Time and Update Order", "4. Vehicles", "5. Consignments (Packages)", "6. Legal Actions Per Tick", "7. Edge Capacity, Queues, and Conflicts", "8. Traffic Signals", "9. Loading and Unloading", "10. Incidents and Road Closures", "11. Priorities and Service Levels", "12. Controller Objectives", "13. Rule Conflicts and Undefined Behavior", "1. Map Overview", "2. Edges", "3. Signal Settings", "4. Vehicles in the Morning Rush Scenario", "5. Consignments", "6. Incidents", "7. Scenario Horizon and Objective", "1. State Snapshot Format", "1.1 GLOBAL Section", "1.2 NODES Section", "1.3 EDGES Section", "1.4 VEHICLES Section", "1.5 CONSIGNMENTS Section", "1.6 INCIDENTS_ACTIVE Section", "2. Worked Example A:Simple Departure", "3. Worked Example B:Signal at Central Intersection", "4. Worked Example C:Capacity Reduction Incident"], "context_snippets": [], "heading_number": "", "heading_kind": "outline_llm", "section_summary": "R1. The Arclight Freight Network (AFN) is a fictional urban road and logistics system used to simulate movement of vehicles and packages over discrete time steps."}}], "supports": [{"support_id": "94617d5e-7661-5b69-8639-9475692426a5", "doc_id": "1291f40b-7db3-5798-9061-f3310b3f99fe", "section": "User Questions", "excerpt": "R47. Undelivered consignments at the end of the scenario incur a lateness equal to (FinalTick + 1:DueTime).

